        "_model_loaded_flag",
        "_disposing",
        "forced_language",
        "_last_detected_language",
        "_torch",
        "_np",
        "_scipy_signal",
        "_last_confidence_threshold",
        "_confidence_lock",
        "_audio_enhancer",
        "_cache_manager",
        "_model_locks",
        "_model_locks_lock",
        "_reloading",
        "_model_load_stop_event",
        "_vad_fallback_enabled",
        "_debug",
