    def _load_custom_profiles(self) -> Dict[str, Dict[str, Any]]:
        """Lädt benutzerdefinierte Profile aus dem Dateisystem."""
        profiles_dir = PlatformUtils.get_platform_config_dir() / "profiles"
        profiles = {}
        if not profiles_dir.exists():
            return profiles
        for file in profiles_dir.glob("*.json"):
            try:
                with open(file, "r", encoding="utf-8") as f:
                    data = json.load(f)
                profiles[file.stem] = data
            except Exception:
                pass
        return profiles

    @staticmethod
    def _is_scroll_inhibited(widget: tk.Widget) -> bool:
        """
        Return True if *widget* should handle mouse wheel events itself
        and not forward them to a surrounding canvas.
        """
        try:
            if not widget.winfo_exists():
                return True
        except (tk.TclError, AttributeError):
            return True

        if isinstance(widget, (tk.Listbox, ttk.Combobox)):
            return True

        if hasattr(widget, "yview") and callable(widget.yview):
            return True

        return False

