    #  Hilfsmethoden für Widget‑Erstellung
    def _add_label_value(
        self, parent: tk.Widget, label: str, value: str, row: int
    ) -> None:
        """Fügt ein Label mit einem statischen Wert hinzu."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        tk.Label(
            parent,
            text=value,
            relief="sunken",
            width=15,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=1, sticky="w", pady=5, padx=5)

    def _add_labeled_spinbox(
        self,
        parent: tk.Widget,
        label: str,
        var: tk.Variable,
        from_val: float,
        to_val: float,
        row: int,
        tooltip: str,
    ) -> None:
        """Fügt eine beschriftete Spinbox hinzu und registriert sie für die Validierung."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        spin = tk.Spinbox(
            parent,
            from_=from_val,
            to=to_val,
            textvariable=var,
            width=self.SPINBOX_WIDTH,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            buttonbackground=self.gui.current_theme.BG_TERTIARY,
        )
        spin.grid(row=row, column=1, sticky="w", pady=5, padx=5)
        ToolTip(spin, tooltip)
        self._spinbox_vars[spin] = var

    def _add_labeled_scale(
        self,
        parent: tk.Widget,
        label: str,
        var: tk.DoubleVar,
        from_val: float,
        to_val: float,
        resolution: float,
        row: int,
        tooltip: str,
    ) -> None:
        """Fügt eine beschriftete ttk.Scale hinzu."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        scale, lbl = self._add_ttk_scale(parent, var, from_val, to_val, resolution)
        scale.grid(row=row, column=1, sticky="ew", pady=5, padx=5)
        lbl.grid(row=row, column=2, padx=5)
        ToolTip(scale, tooltip)

    def _add_ttk_scale(
        self,
        parent: tk.Widget,
        var: tk.DoubleVar,
        from_val: float,
        to_val: float,
        resolution: float,
    ):
        """Erstellt eine ttk.Scale mit zugehörigem Wertelabel."""
        scale = ttk.Scale(
            parent,
            from_=from_val,
            to=to_val,
            variable=var,
            orient=tk.HORIZONTAL,
            length=self.SCALE_LENGTH,
        )
        value_label = tk.Label(
            parent,
            textvariable=var,
            width=5,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        )
        var.trace_add(
            "write", lambda *args: value_label.config(text=f"{var.get():.2f}")
        )
        return scale, value_label

    def _create_packages_tab(self) -> None:
        """
        Erstellt den Inhalt des Tabs „📦 Pakete & Updates“ (Lazy Loading).
        """
        parent = self._make_scrollable(self.tab_packages)

        creation_errors = []

        def safe_create(widget_cls, parent, **kwargs):
            """Erstellt ein tk‑Widget und fängt TclError ab."""
            try:
                widget = widget_cls(parent, **kwargs)
                return widget
            except tk.TclError as e:
                creation_errors.append(str(e))
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "packages_tab",
                        f"Fehler beim Erstellen von {widget_cls.__name__}: {e}",
                    )
                return tk.Label(parent, text="⚠️", bg="red", fg="white")

        # =================================================================
        # 1. Optionale Python‑Pakete (LabelFrame)
        # =================================================================
        pkg_frame = tk.LabelFrame(
            parent,
            text="📦 Optionale Python‑Pakete",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=10,
            relief="flat",
            bd=0,
            highlightthickness=0,
        )
        pkg_frame.pack(fill="x", padx=5, pady=5)

        # Liste der zu überprüfenden Pakete (Name, aktueller Status)
        package_specs = [
            ("deep-translator", TRANSLATOR_AVAILABLE),
            ("faster-whisper", WHISPER_AVAILABLE),
            ("psutil", FastLazyLoader.is_available("psutil")),
            ("pynvml", importlib.util.find_spec("pynvml") is not None),
            ("argos-translate", ARGOS_AVAILABLE),
            ("rapidfuzz", importlib.util.find_spec("rapidfuzz") is not None),
            ("python-docx", importlib.util.find_spec("docx") is not None),
        ]

        # Wichtig: self.package_labels initialisieren, damit _refresh_package_status
        #          später darauf zugreifen kann.
        self.package_labels: List[Tuple[str, tk.Label]] = []

        for i, (name, available) in enumerate(package_specs):
            status = "✅" if available else "❌"
            text = f"{status} {name}"
            lbl = safe_create(
                tk.Label,
                pkg_frame,
                text=text,
                anchor="w",
                bg=self.gui.current_theme.BG_SECONDARY,
                fg=self.gui.current_theme.SUCCESS
                if available
                else self.gui.current_theme.ERROR,
                font=Fonts.PRIMARY,
            )
            lbl.grid(row=i, column=0, sticky="w", pady=2, padx=5)
            self.package_labels.append((name, lbl))

        # Button, der den großen Installationsdialog öffnet
        btn_frame = tk.Frame(pkg_frame, bg=self.gui.current_theme.BG_SECONDARY)
        btn_frame.grid(row=len(package_specs), column=0, pady=10, sticky="w")

        def open_install_dialog_and_refresh():
            """Öffnet den Installationsdialog und aktualisiert danach die Statusanzeige."""
            dlg = InstallDependencyDialog(self.dialog, self.gui)
            # Warten, bis der modale Dialog geschlossen ist
            self.dialog.wait_window(dlg.dialog)
            # Status der Pakete neu laden
            self._on_packages_installed()
            if DEBUG_LEVEL >= 3:
                log_debug("packages_tab", "Paket‑Status nach Installation aktualisiert")

        install_btn = safe_create(
            tk.Button,
            btn_frame,
            text="📦 Fehlende Pakete installieren",
            command=open_install_dialog_and_refresh,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
            padx=5,
            cursor="hand2",
            relief="flat",
            bd=1,
            activebackground=self.gui.current_theme.BG_HOVER,
            activeforeground=self.gui.current_theme.TEXT_ACCENT,
        )
        install_btn.pack(side="left", padx=2)
        ToolTip(
            install_btn,
            "Öffnet den vollständigen Assistenten zum Installieren\n"
            "fehlender Pakete und Piper‑Stimmen.",
        )

        update_frame = tk.LabelFrame(
            parent,
            text="🔄 pip‑Pakete aktualisieren",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=10,
            relief="flat",
            bd=0,
            highlightthickness=0,
        )
        update_frame.pack(fill="x", padx=5, pady=5)

        btn_row1 = tk.Frame(update_frame, bg=self.gui.current_theme.BG_SECONDARY)
        btn_row1.pack(fill="x")

        crit_btn = safe_create(
            tk.Button,
            btn_row1,
            text="⚠️ Kritische Pakete aktualisieren",
            command=self._update_critical_packages,
            bg=self.gui.current_theme.WARNING,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
            padx=5,
            cursor="hand2",
            relief="flat",
            bd=1,
            activebackground=self.gui.current_theme.BG_HOVER,
            activeforeground=self.gui.current_theme.TEXT_ACCENT,
        )
        crit_btn.pack(side="left", padx=2)
        ToolTip(
            crit_btn,
            "Aktualisiert nur die wichtigsten Pakete:\n"
            f"{', '.join(InstallDependencyDialog.CRITICAL_PYTHON_PACKAGES)}",
        )

        all_btn = safe_create(
            tk.Button,
            btn_row1,
            text="📦 Alle pip‑Pakete aktualisieren",
            command=self._update_all_pip_packages,
            bg=self.gui.current_theme.DRAGON_GREEN,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
            padx=5,
            cursor="hand2",
            relief="flat",
            bd=1,
            activebackground=self.gui.current_theme.BG_HOVER,
            activeforeground=self.gui.current_theme.TEXT_ACCENT,
        )
        all_btn.pack(side="left", padx=2)
        ToolTip(
            all_btn,
            "Aktualisiert alle installierten pip‑Pakete (kann einige Minuten dauern).",
        )

        self._update_status_label = safe_create(
            tk.Label,
            update_frame,
            text="",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_SECONDARY,
            font=Fonts.SMALL,
        )
        self._update_status_label.pack(pady=(5, 0))

        sys_frame = tk.LabelFrame(
            parent,
            text="🖥️ Systempakete (externe Tools)",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=10,
            relief="flat",
            bd=0,
            highlightthickness=0,
        )
        sys_frame.pack(fill="x", padx=5, pady=5)

        # Hilfsfunktion, um zu prüfen, ob ein Tool installiert ist
        def _tool_installed(name: str) -> bool:
            if name == "vlc":
                return InstallDependencyDialog._is_vlc_installed()
            return shutil.which(name) is not None

        sys_packages = ["ffmpeg", "yt-dlp", "vlc", "espeak", "piper", "ollama"]

        for pkg_name in sys_packages:
            installed = _tool_installed(pkg_name)
            status = "✅" if installed else "❌"
            color = (
                self.gui.current_theme.SUCCESS
                if installed
                else self.gui.current_theme.ERROR
            )
            text = f"{status} {pkg_name}"
            if not installed:
                text += " (fehlt)"

            lbl = safe_create(
                tk.Label,
                sys_frame,
                text=text,
                anchor="w",
                bg=self.gui.current_theme.BG_SECONDARY,
                fg=color,
                font=Fonts.PRIMARY,
            )
            lbl.pack(fill="x", pady=1)

        info_label = safe_create(
            tk.Label,
            sys_frame,
            text="💡 Piper‑Stimmen können über den Button "
            "'📦 Fehlende Pakete installieren' heruntergeladen werden.",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_SECONDARY,
            font=Fonts.SMALL,
            justify="left",
        )
        info_label.pack(anchor="w", pady=5)

        if creation_errors:
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "packages_tab",
                    f"{len(creation_errors)} Widget‑Fehler aufgetreten, "
                    f"Details: {'; '.join(creation_errors)}",
                )
            error_lbl = safe_create(
                tk.Label,
                parent,
                text="⚠️ Einige Steuerelemente konnten nicht geladen werden.",
                bg=self.gui.current_theme.BG_PRIMARY,
                fg=self.gui.current_theme.WARNING,
                font=Fonts.SMALL,
            )
            error_lbl.pack(pady=(5, 0))

        search_texts = [
            "pakete",
            "updates",
            "optional",
            "fehlende",
            "installieren",
            "pip",
            "python",
            "systempakete",
            "deep-translator",
            "faster-whisper",
            "psutil",
            "pynvml",
            "argos-translate",
            "rapidfuzz",
            "python-docx",
            "fehlende pakete installieren",
            "kritische pakete aktualisieren",
            "alle pip-pakete aktualisieren",
            "ffmpeg",
            "yt-dlp",
            "vlc",
            "espeak",
            "piper",
            "ollama",
            "piper-stimmen",
        ]
        for name, _ in package_specs:
            search_texts.append(name.lower())
            search_texts.append(f"{name} fehlt")
        for pkg_name in sys_packages:
            search_texts.append(pkg_name.lower())
            search_texts.append(f"{pkg_name} installiert")

        self._add_to_search_index("packages", search_texts)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "packages_tab",
                "Tab 'Pakete & Updates' vollständig und optimiert aufgebaut",
            )

