    def show_install_dialog(self) -> None:
        """
        Öffnet den Installationsdialog für fehlende Pakete.
        """
        if self.is_shutting_down():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dialog", "GUI im Shutdown – Dialog wird nicht geöffnet"
                )
            return

        if hasattr(self, "_install_dialog") and self._install_dialog is not None:
            dlg = self._install_dialog
            try:
                if dlg.dialog.winfo_exists():
                    # Dialog existiert – nur in den Vordergrund holen
                    dlg.dialog.lift()
                    dlg.dialog.focus_force()
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "install_dialog",
                            "Vorhandener Dialog in den Vordergrund geholt",
                        )
                    return
                else:
                    # Widget wurde zerstört, aber Referenz existiert noch
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "install_dialog",
                            "Dialog-Referenz existiert, aber Widget zerstört – neu erstellen",
                        )
                    self._install_dialog = None
            except (tk.TclError, AttributeError) as e:
                logger.warning(f"Fehler beim Prüfen des vorhandenen Dialogs: {e}")
                self._install_dialog = None  # Sicherer Reset

        try:
            dlg = InstallDependencyDialog(self.root, self)
        except Exception as e:
            logger.error(
                f"Konnte InstallDependencyDialog nicht erstellen: {e}", exc_info=True
            )
            self.update_status("❌ Fehler beim Öffnen des Installationsdialogs")
            return

        self._install_dialog = dlg

        def on_destroy():
            """Setzt die Referenz zurück, sobald das Fenster geschlossen wird."""
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dialog", "Dialog geschlossen – Referenz zurückgesetzt"
                )
            self._install_dialog = None

        # Protokolliere sowohl den Fenster-Close als auch den programmatischen close()
        dlg.dialog.protocol("WM_DELETE_WINDOW", lambda: [on_destroy(), dlg.close()])

        original_close = dlg.close

        def _close_wrapper():
            on_destroy()
            original_close()

        dlg.close = _close_wrapper

        if DEBUG_LEVEL >= 2:
            log_debug("install_dialog", "Neuer Installationsdialog geöffnet")

    @gui_operation_decorator
    def run_system_check(self) -> None:
        import io
        import logging

        log_stream = io.StringIO()
        handler = logging.StreamHandler(log_stream)
        handler.setLevel(logging.INFO)
        logger.addHandler(handler)
        try:
            success = PlatformUtils.check_platform_dependencies()
            if success:
                msg = "✅ Alle kritischen Abhängigkeiten sind vorhanden."
                output = log_stream.getvalue()
                if output:
                    relevant = [
                        line
                        for line in output.splitlines()
                        if "⚠️" in line or "✓" in line
                    ]
                    if relevant:
                        msg += "\n\nDetails:\n" + "\n".join(relevant)
                DarkMessageBox.showinfo("System-Check", msg, self.root)
            else:
                DarkMessageBox.showwarning(
                    "System-Check", "Einige kritische Abhängigkeiten fehlen.", self.root
                )
        except RuntimeError as e:
            DarkMessageBox.showerror(
                "System-Check – Fehlende Abhängigkeiten", str(e), self.root
            )
        except Exception as e:
            DarkMessageBox.showerror(
                "System-Check", f"Unerwarteter Fehler: {e}", self.root
            )
        finally:
            logger.removeHandler(handler)
            log_stream.close()

    def show_shortcuts_help(self) -> None:
        ShortcutsDialog(self.root)

    def update_translation_engine(self) -> None:
        """
        Aktualisiert die Übersetzungs-Engine basierend auf den aktuellen Einstellungen.
        """
        try:
            new_engine = self._create_translation_engine()
            new_engine.set_target_language(self.current_language)
            self.translation_engine = new_engine
            if hasattr(self, "audio_processor") and self.audio_processor:
                self.audio_processor.translation_engine = new_engine
            logger.info(
                f"Translation engine updated to {self.advanced_settings.translation_engine}"
            )
        except Exception as e:
            logger.error(f"Failed to create new translation engine: {e}")

    def _create_translation_engine(self) -> BaseTranslationEngine:
        engine_name = self.advanced_settings.translation_engine
        enable_reflection = getattr(self.advanced_settings, "enable_reflection", False)
        base_engine = self._create_engine_by_name(
            engine_name, self.current_language, for_dialog=False
        )
        if base_engine is None:
            if engine_name != "google" and TRANSLATOR_AVAILABLE:
                base_engine = GoogleTranslationEngine(
                    self.current_language,
                    self.advanced_settings,
                    self.app_context.cache_manager,
                )
            else:
                return DummyTranslationEngine(
                    self.current_language,
                    self.advanced_settings,
                    self.app_context.cache_manager,
                )
        if (
            enable_reflection
            and hasattr(base_engine, "_call_ollama")
            and "ReflectionTranslationEngine" in globals()
        ):
            try:
                return ReflectionTranslationEngine(base_engine, self.advanced_settings)
            except Exception:
                pass
        return base_engine

    def _create_engine_by_name(
        self, engine_name: str, target_lang: str, for_dialog: bool = False
    ) -> Optional[BaseTranslationEngine]:
        if engine_name == "google":
            if TRANSLATOR_AVAILABLE:
                return GoogleTranslationEngine(
                    target_lang, self.advanced_settings, self.app_context.cache_manager
                )
        elif engine_name == "ollama":
            if OLLAMA_AVAILABLE:
                timeout = (
                    15
                    if for_dialog
                    else getattr(self.advanced_settings, "ollama_timeout", 45)
                )
                return OllamaTranslationEngine(
                    target_lang,
                    self.advanced_settings,
                    self.advanced_settings.ollama_model,
                    self.advanced_settings.ollama_host,
                    timeout,
                    cache_manager=self.app_context.cache_manager,
                )
        elif engine_name == "argos":
            if ARGOS_AVAILABLE:
                engine = ArgosTranslateEngine(
                    target_lang, self.advanced_settings, self.app_context.cache_manager
                )
                if engine.is_functional():
                    return engine
        return None

    def _create_temporary_translation_engine(
        self, engine_name: str, target_lang: str
    ) -> Optional[BaseTranslationEngine]:
        return self._create_engine_by_name(engine_name, target_lang, for_dialog=True)

    def _start_system_monitoring(self) -> None:
        def monitor():
            if self.is_shutting_down() or not self.root.winfo_exists():
                return
            info = self._build_system_info_string()
            self._safe_gui_update(lambda: self.system_info_label.config(text=info))
            self._safe_after(3000, monitor)

        self._safe_after(1000, monitor)

    def _build_system_info_string(self) -> str:
        """
        Erzeugt einen kompakten Status‑String für die Systemüberwachung.
        """

        # 1. CPU‑ und RAM‑Werte (mit Fallback für fehlendes psutil)
        cpu_str = "--"
        ram_str = "--/--G"
        try:
            import psutil

            cpu = psutil.cpu_percent(interval=None)
            mem = psutil.virtual_memory()
            ram_used = mem.used / (1024**3)
            ram_total = mem.total / (1024**3)
            cpu_str = f"{cpu:.0f}"
            ram_str = f"{ram_used:.1f}/{ram_total:.1f}G"
        except ImportError:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui", "psutil nicht verfügbar – CPU/RAM-Anzeige deaktiviert."
                )
        except Exception as e:
            logger.warning(f"Fehler beim Abrufen der Systeminformationen: {e}")

        # 2. GPU‑Informationen (VRAM) – über bereits robuste Hilfsmethode
        gpu_info = self._get_gpu_info_string()

        # 3. Whisper‑Modell ermitteln (sicher)
        model_name = "not loaded"
        try:
            if (
                hasattr(self, "transcription_engine")
                and self.transcription_engine is not None
            ):
                engine = self.transcription_engine
                model_name = engine.get_current_model()
                if model_name == "None":
                    model_name = "not loaded"
        except Exception:
            pass

        # 4. Plattform‑Kürzel
        if IS_WINDOWS:
            platform_short = "🪟Windows"
        elif IS_MACOS:
            platform_short = "🍎Mac"
        elif IS_LINUX:
            platform_short = "🐧Linux"
        else:
            platform_short = "🌐OS"

        # 5. Zusammenbau des Gesamtstrings
        demo_hint = " (demo)" if self.demo_mode else ""
        info_string = (
            f"{platform_short} | CPU: {cpu_str}% | RAM: {ram_str}"
            f"{gpu_info} | Model: {model_name}{demo_hint}"
        )
        return info_string

    def _get_gpu_info_string(self) -> str:
        try:
            import pynvml

            pynvml.nvmlInit()
            handle = pynvml.nvmlDeviceGetHandleByIndex(0)
            mem = pynvml.nvmlDeviceGetMemoryInfo(handle)
            used = mem.used / (1024**3)
            total = mem.total / (1024**3)
            return f" | VRAM: {used:.1f}/{total:.1f}G"
        except Exception:
            if TORCH_AVAILABLE:
                try:
                    import torch

                    if torch.cuda.is_available():
                        used = torch.cuda.memory_allocated() / (1024**3)
                        total = torch.cuda.get_device_properties(0).total_memory / (
                            1024**3
                        )
                        return f" | VRAM: {used:.1f}/{total:.1f}G (via torch)"
                except Exception:
                    pass
        return " | VRAM: n/a"

    def _final_initialization_check(self) -> None:
        logger.info("✅ Dragon Whisperer initialisiert")
        if self.demo_mode:
            self.update_status(
                "⚠️ Demo-Modus: Whisper nicht verfügbar – verwende Dummy-Transkriptionen"
            )
        self._safe_after(500, self._update_ollama_button_state)
        self._update_vad_fallback_button()
        self._update_live_mode_button()

    def _update_ollama_button_state(self) -> None:
        if not hasattr(self, "correct_btn") or not OLLAMA_AVAILABLE:
            return

        def check():
            summarizer = OllamaSummarizer(
                self,
                model=self.advanced_settings.ollama_model,
                host=self.advanced_settings.ollama_host,
            )
            reachable = summarizer.is_server_reachable()
            summarizer.dispose()
            self._safe_gui_update(lambda: self._set_correct_btn_state(reachable))

        threading.Thread(target=check, daemon=True, name="OllamaServerCheck").start()

    def _set_correct_btn_state(self, reachable: bool) -> None:
        if not reachable:
            self.correct_btn.config(state="disabled", text="🔧 (Server aus)")
            ToolTip(
                self.correct_btn, "Ollama-Server läuft nicht – starte 'ollama serve'"
            )
        else:
            self.correct_btn.config(state="normal", text="🔧")
            ToolTip(self.correct_btn, "Transkript mit Ollama korrigieren")

    def _schedule_gui_health_check(self) -> None:
        if not self.is_shutting_down() and self.root.winfo_exists():
            self._safe_after(30000, self._perform_gui_health_check)

    def _perform_gui_health_check(self) -> None:
        try:
            if hasattr(self, "memory_manager"):
                mem_stats = self.memory_manager.get_memory_stats()
                if mem_stats.get("process_usage_percent", 0) > 85:
                    self.memory_manager.aggressive_cleanup()
            for attr in ("transcript_text", "translation_text"):
                widget = getattr(self, attr, None)
                if widget and widget.winfo_exists():
                    self._trim_text_widget(widget, attr)
            self._schedule_gui_health_check()
        except Exception as e:
            logger.warning(f"⚠️ Health check error: {e}")

    def _trim_text_widget(self, widget: tk.Text, attr: str) -> None:
        try:
            lines = int(widget.index("end-1c").split(".")[0])
            max_lines = (
                self.advanced_settings.transcript_max_lines
                if attr == "transcript_text"
                else self.advanced_settings.translation_max_lines
            )
            if lines > max_lines * 1.2:
                keep = max_lines - 100
                widget.delete("1.0", f"{lines - keep}.0")
                self.update_status(f"📝 {attr.replace('_', ' ')} gekürzt")
        except Exception:
            pass

    def _start_gui_updaters(self) -> None:
        if not self.is_shutting_down() and self.root.winfo_exists():
            self.queue_manager.start()
            self._safe_after(5000, self._check_queue_sizes)

    def _check_queue_sizes(self) -> None:
        if self.queue_manager and not self.is_shutting_down():
            self.queue_manager._check_queue_sizes()

    # VRAM-Idle-Timeout
    def _schedule_vram_idle_check(self) -> None:
        if self._vram_idle_timer is not None:
            try:
                self.root.after_cancel(self._vram_idle_timer)
            except (ValueError, tk.TclError):
                pass
        self._vram_idle_timer = self.root.after(60000, self._check_vram_idle)

    def _check_vram_idle(self) -> None:
        """
        Prüft, ob das Whisper‑Modell aufgrund von Inaktivität aus dem VRAM
        entladen werden kann. Verhindert mehrfaches Entladen durch
        Deaktivierung des Timers nach erfolgreichem Entladen.
        """
        # 1. Frühzeitiger Ausstieg bei Shutdown oder fehlender GUI
        if getattr(self, "_shutting_down", False) or not self.root.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "vram",
                    "_check_vram_idle: Shutdown oder GUI nicht verfügbar – Abbruch",
                )
            return

        # 2. Timeout aus den Einstellungen lesen (0 = deaktiviert)
        try:
            timeout = self.advanced_settings.vram_idle_timeout_seconds
        except AttributeError:
            logger.warning(
                "_check_vram_idle: advanced_settings nicht verfügbar – Timer wird nicht neu gestartet"
            )
            return

        if timeout <= 0:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "vram",
                    f"_check_vram_idle: Timeout {timeout}s – VRAM‑Idle‑Check deaktiviert",
                )
            self._schedule_vram_idle_check()
            return

        # 3. Wenn eine Transkription läuft, wird die letzte Aktivität aktualisiert und der Timer neu gestartet.
        if self.is_processing:
            self._last_transcription_time = time.time()
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "vram",
                    "_check_vram_idle: Verarbeitung aktiv – Idle‑Zeit zurückgesetzt",
                )
            self._schedule_vram_idle_check()
            return

        # 4. Idle‑Zeit berechnen
        idle_seconds = time.time() - self._last_transcription_time
        if idle_seconds < timeout:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "vram",
                    f"_check_vram_idle: {idle_seconds:.1f}s < {timeout}s – noch nicht reif",
                )
            self._schedule_vram_idle_check()
            return

        # 5. Timeout erreicht – Modell entladen, falls vorhanden
        logger.info(
            f"💤 VRAM‑Idle‑Timeout ({timeout}s) erreicht – versuche, Whisper‑Modell zu entladen"
        )

        engine = getattr(self, "transcription_engine", None)
        if engine is None:
            logger.warning(
                "_check_vram_idle: Keine transcription_engine – Timer wird gestoppt"
            )
            self._set_vram_button_disabled()
            return

        # 5.1 Modellnamen ermitteln (sicher)
        try:
            current_model = engine.get_current_model()
        except Exception as e:
            logger.error(f"_check_vram_idle: Fehler beim Abrufen des Modellnamens: {e}")
            self._schedule_vram_idle_check()
            return

        if not current_model or current_model in ("None", "not loaded", "dummy"):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "vram",
                    f"_check_vram_idle: Kein Modell geladen ({current_model}) – Timer wird nicht neu gestartet",
                )
            self._set_vram_button_disabled()
            return

        # 5.2 Modell entladen (mit Fallback für Engines ohne die Methode)
        try:
            if hasattr(engine, "_force_model_cleanup"):
                engine._force_model_cleanup()
                logger.info("✅ Whisper‑Modell aus VRAM entladen")
            else:
                logger.warning(
                    f"_check_vram_idle: Engine {type(engine).__name__} unterstützt "
                    f"kein _force_model_cleanup – Modell wird auf None gesetzt"
                )
                with (
                    engine._model_usage_lock
                    if hasattr(engine, "_model_usage_lock")
                    else threading.RLock()
                ):
                    engine.model = None
                    engine.model_size = None
        except Exception as e:
            logger.error(
                f"_check_vram_idle: Fehler beim Entladen des Modells: {e}",
                exc_info=True,
            )

        # 5.3 GUI‑Status aktualisieren
        self.update_status(
            f"💤 Whisper‑Modell aus VRAM entladen (Inaktivität > {timeout}s)"
        )
        self._last_transcription_time = 0.0

        # 5.4 VRAM‑Button deaktivieren und Timer stoppen – Modell ist jetzt entladen
        self._set_vram_button_disabled()

    def _set_vram_button_disabled(self) -> None:
        """
        Setzt den VRAM‑Entlade‑Button auf 'disabled', falls er existiert.
        """
        if (
            hasattr(self, "vram_unload_btn")
            and self.vram_unload_btn is not None
            and self.vram_unload_btn.winfo_exists()
        ):
            try:
                self.vram_unload_btn.config(state="disabled")
                if DEBUG_LEVEL >= 4:
                    log_debug("vram", "VRAM‑Button deaktiviert")
            except tk.TclError:
                pass

